'use strict';
let personalBusy=false,personalRefreshing=false,personalCurrency='USD',personalChartPoints=[];
const personalColors=['#196748','#598fc4','#ba7656','#8d71b4','#c9a147','#41968f','#ad637d','#728b53'];
function personalChart(points,currency){
 if(points.length<2)return '<p class="muted">At least two matching historical closes are needed. History appears after prices load.</p>';
 personalChartPoints=points;const values=points.map(p=>p.value),lo=Math.min(0,...values),hi=Math.max(0,...values),y=v=>105-(v-lo)/Math.max(1,hi-lo)*90,path=points.map((p,i)=>`${i?'L':'M'}${10+i/(points.length-1)*580},${y(p.value)}`).join(' ');
 return `<svg viewBox="0 0 600 135" role="img" aria-label="Recorded investment profit and loss history in ${currency}"><line x1="10" x2="590" y1="${y(0)}" y2="${y(0)}" stroke="#ccd9d1" stroke-dasharray="3 4"/><path d="${path}" fill="none" stroke="#258666" stroke-width="2.5"/><text x="10" y="130">${date(points[0].date)}</text><text x="590" y="130" text-anchor="end">${date(points.at(-1).date)}</text><title>${points.map(p=>date(p.date)+': '+money(p.value,currency)).join('\n')}</title></svg><input id="personalScrub" type="range" min="0" max="${points.length-1}" value="${points.length-1}" aria-label="Explore portfolio history"><output id="personalReadout">${date(points.at(-1).date)} · ${money(points.at(-1).value,currency)}</output><small>${money(Math.min(...values),currency)} low · ${money(Math.max(...values),currency)} high · ${points.length} matched sessions</small>`;
}
function renderPersonal(){
 if(!$('#portfolioView'))return;const tx=workspaceState.portfolioTransactions||[],currencies=[...new Set(tx.map(t=>t.currency))];if(currencies.length&&!currencies.includes(personalCurrency))personalCurrency=currencies[0];
 $('#personalCurrency').innerHTML=(currencies.length?currencies:['USD']).map(c=>`<option ${c===personalCurrency?'selected':''}>${c}</option>`).join('');
 $('#personalSync').textContent=!workspaceReady?'Connecting to saved portfolio…':workspaceState.user?'Private · saved to your account':'Saved for this browser session identity · sign in before entering holdings for cross-device access. Guest entries are separate from your account.';
 const v=personalValuation(tx,currentPortfolioPrices(),personalCurrency),fmt=n=>n===null?'—':money(n,personalCurrency),stat=(label,n,note)=>`<article><small>${label}</small><strong ${quoteNumberAttrs('portfolio:'+personalCurrency+':'+label,n)} class="${n!==null&&n<0?'loss':''}">${fmt(n)}</strong><small>${note}</small></article>`;
 $('#personalStats').innerHTML=stat('Holdings value',v.value,v.missing?v.missing+' positions need matching quotes':'Latest available quotes · excludes cash')+stat('Remaining cost',v.cost,'Weighted average · includes buy fees')+stat('Unrealized gain / loss',v.unrealized,v.unrealized!==null&&v.cost? signed(v.unrealized/v.cost*100)+' on remaining cost':'Open holdings')+stat('Realized gain / loss',v.realized,'Recorded sales · net of fees')+stat('Dividends',v.dividends,'Recorded payments · net of fees')+stat('Total investment P/L',v.total,'Realized + unrealized + dividends');
 const usable=v.rows.filter(p=>p.value!==null&&p.value>0).sort((a,b)=>b.value-a.value);let cursor=0;
 const stops=usable.map((p,i)=>{const from=cursor;cursor+=p.value/v.pricedValue*100;return `${personalColors[i%8]} ${from}% ${cursor}%`});
 $('#personalAllocation').innerHTML=usable.length?`<div class="personal-allocation"><div class="personal-pie" style="background:conic-gradient(${stops.join(',')})" role="img" aria-label="Holdings allocation by current value, ${personalCurrency}"><span>${usable.length}<small>holdings</small></span></div><div>${usable.map((p,i)=>`<button data-ticker="${esc(p.symbol)}"><i style="background:${personalColors[i%8]}"></i><b>${esc(p.symbol)}</b><span>${(100*p.value/v.pricedValue).toFixed(1)}%</span></button>`).join('')}</div></div><small>${v.missing?'Partial allocation: unpriced positions excluded.':'Current market value by ticker.'} ${personalCurrency} only.</small>`:'<p class="muted">Add holdings to see your allocation. Unavailable or mismatched currencies are excluded.</p>';
 $('#personalGrowth').innerHTML=personalChart(personalHistory(tx,PRICES,personalCurrency),personalCurrency);
 $('#personalHoldings').innerHTML=v.rows.map(p=>`<tr><td><button data-ticker="${esc(p.symbol)}"><b>${esc(p.symbol)}</b></button><small>${date(p.firstBuy)}</small></td><td>${p.quantity.toLocaleString('en-US',{maximumFractionDigits:8})}</td><td>${fmt(p.average)}</td><td><span ${quoteNumberAttrs('holding:'+p.symbol+':value:'+personalCurrency,p.value)}>${fmt(p.value)}</span><small>${p.value===null?'Quote unavailable / currency mismatch':quoteLabel(p.quote)}</small></td><td class="${p.profit!==null&&p.profit<0?'loss':'gain'}"><span ${quoteNumberAttrs('holding:'+p.symbol+':profit:'+personalCurrency,p.profit)}>${fmt(p.profit)}</span><small>${p.profit!==null&&p.cost?signed(p.profit/p.cost*100):'—'}</small></td><td><button data-map="${esc(p.symbol)}">Map ↗</button></td></tr>`).join('')||'<tr><td colspan="6">No open holdings in this currency. Record your first purchase below.</td></tr>';
 $('#personalTransactions').innerHTML=[...tx].sort((a,b)=>b.date.localeCompare(a.date)||b.order-a.order).map(t=>`<tr><td>${date(t.date)}</td><td><button data-ticker="${esc(t.symbol)}">${esc(t.symbol)}</button></td><td>${esc(t.type)}</td><td>${t.type==='dividend'?'—':t.quantity}</td><td>${money(t.price,t.currency)}</td><td>${money(t.fees,t.currency)}</td><td>${esc(t.notes)}</td><td><button data-personal-edit="${esc(t.id)}">Edit</button><button data-personal-delete="${esc(t.id)}">Remove</button></td></tr>`).join('')||'<tr><td colspan="8">No transactions yet.</td></tr>';
 $('#personalSave').disabled=personalBusy||!workspaceReady;
}
async function refreshPersonal(){if(personalBusy||personalRefreshing)return;personalRefreshing=true;try{renderPersonal();await workspaceAction();renderPersonal();const symbols=[...new Set((workspaceState.portfolioTransactions||[]).map(t=>t.symbol))];await loadMarketPrices(symbols);renderPersonal()}finally{personalRefreshing=false}}
function personalReset(){ $('#personalForm').reset();$('#personalId').value='';$('#personalDate').value=new Date().toISOString().slice(0,10).split('-').reverse().join('-');$('#personalFees').value='0';$('#personalEditState').textContent='Add transaction';$('#personalSave').textContent='Save transaction';personalType()}
function personalType(){const dividend=$('#personalType').value==='dividend';$('#personalQuantity').disabled=dividend;$('#personalQuantity').required=!dividend;$('#personalPriceLabel').textContent=dividend?'Total dividend received':'Price per share / average price'}
(()=>{
 const section=$('#portfolioView');section.innerHTML=`<div class="home-heading"><h1>My portfolio</h1><div><select id="personalCurrency" aria-label="Portfolio reporting currency"><option>USD</option></select><button id="personalRefresh" class="secondary">Refresh prices</button><button id="personalExport" class="secondary">Export CSV</button></div></div><p id="personalSync" class="home-caption"></p><div id="personalStats" class="personal-stats"></div><div class="personal-visuals"><section class="panel"><h2>Allocation</h2><div id="personalAllocation"></div></section><section class="panel"><h2>Investment P/L history</h2><div id="personalGrowth"></div><p class="home-caption">Up to 365 matched sessions; missing dates omitted · based on recorded transactions and daily closes. Contributions are not profit; this is P/L, not a deposit-adjusted return rate.</p></section></div><section class="home-section"><div class="home-heading"><h2>Open holdings</h2></div><div class="table-scroll"><table><thead><tr><th>Stock / first buy</th><th>Shares</th><th>Avg cost</th><th>Value / quote date</th><th>Unrealized P/L</th><th></th></tr></thead><tbody id="personalHoldings"></tbody></table></div></section><section class="home-section"><h2 id="personalEditState">Add transaction</h2><form id="personalForm" class="personal-form"><input id="personalId" type="hidden"><label>Type<select id="personalType"><option value="buy">Buy / opening holding</option><option value="sell">Sell</option><option value="dividend">Dividend</option></select></label><label>Ticker<input id="personalSymbol" required maxlength="12" placeholder="VOO" autocapitalize="characters"></label><label>Date · DD-MM-YYYY<input id="personalDate" required placeholder="28-09-2026" inputmode="numeric" pattern="[0-9]{2}-[0-9]{2}-[0-9]{4}"></label><label>Shares<input id="personalQuantity" required type="number" min="0.00000001" step="any" placeholder="10"></label><label><span id="personalPriceLabel">Price per share / average price</span><input id="personalPrice" required type="number" min="0.00000001" step="any" placeholder="100"></label><label>Currency<select id="personalTradeCurrency">${['USD','EUR','GBP','CAD','CHF','JPY','AUD'].map(c=>`<option>${c}</option>`).join('')}</select></label><label>Fees<input id="personalFees" type="number" min="0" step="any" value="0" required></label><label class="personal-notes">Notes<input id="personalNotes" maxlength="500" placeholder="Broker, account or investment thesis"></label><button id="personalSave" class="primary">Save transaction</button><button id="personalCancel" class="secondary" type="button">Clear</button><p id="personalFormStatus" role="status"></p></form><p class="home-caption">For an existing holding, enter current shares and your average purchase price. For an accurate historical chart, enter each trade separately. Fees entered here are added to cost; use zero if already included in your average.</p></section><details class="home-section" open><summary>Transaction history</summary><div class="table-scroll"><table><thead><tr><th>Date</th><th>Ticker</th><th>Type</th><th>Shares</th><th>Price / payment</th><th>Fees</th><th>Notes</th><th></th></tr></thead><tbody id="personalTransactions"></tbody></table></div></details><p class="home-caption">Manual portfolio tracking, not brokerage synchronization. No cash balance, FX conversion, taxes or automatic dividends/splits. Record dividends yourself; reconcile share quantities and costs after corporate actions. Historical prices can be split-adjusted, so check history around splits. Totals are unavailable when a held position has no matching quote; stale prices remain labeled.</p>`;
 personalReset();renderPersonal();
 setInterval(()=>{if(view==='portfolio'&&!document.hidden)refreshPersonal()},15*60000);
 document.addEventListener('visibilitychange',()=>{if(view==='portfolio'&&!document.hidden)refreshPersonal()});
 document.addEventListener('input',e=>{if(e.target.id==='personalScrub'){const p=personalChartPoints[Number(e.target.value)];if(p)$('#personalReadout').textContent=date(p.date)+' · '+money(p.value,personalCurrency)}});
 $('#personalType').onchange=personalType;$('#personalCancel').onclick=personalReset;$('#personalCurrency').onchange=e=>{personalCurrency=e.target.value;renderPersonal()};$('#personalRefresh').onclick=refreshPersonal;
 $('#personalForm').onsubmit=async e=>{e.preventDefault();if(personalBusy)return;personalBusy=true;$('#personalSave').disabled=true;const tx={id:$('#personalId').value||crypto.randomUUID(),type:$('#personalType').value,symbol:$('#personalSymbol').value.trim().toUpperCase(),date:$('#personalDate').value.split('-').reverse().join('-'),quantity:Number($('#personalQuantity').value),price:Number($('#personalPrice').value),currency:$('#personalTradeCurrency').value,fees:Number($('#personalFees').value),notes:$('#personalNotes').value.trim()};try{personalValidate(tx);const ok=await workspaceAction({kind:'portfolioSave',revision:workspaceState.portfolioRevision||0,transaction:tx});if(ok){personalCurrency=tx.currency;personalReset();$('#personalFormStatus').textContent='Saved';await loadMarketPrices([tx.symbol])}else $('#personalFormStatus').textContent='Not saved. Check the message and retry; refresh if another device changed the portfolio.'}catch(error){$('#personalFormStatus').textContent=error.message}finally{personalBusy=false;renderPersonal()}};
 document.addEventListener('click',async e=>{const edit=e.target.closest('[data-personal-edit]'),remove=e.target.closest('[data-personal-delete]');if(edit){const t=workspaceState.portfolioTransactions.find(t=>t.id===edit.dataset.personalEdit);if(!t)return;for(const [id,key]of [['personalId','id'],['personalType','type'],['personalSymbol','symbol'],['personalQuantity','quantity'],['personalPrice','price'],['personalTradeCurrency','currency'],['personalFees','fees'],['personalNotes','notes']])$('#'+id).value=t[key];$('#personalDate').value=t.date.split('-').reverse().join('-');$('#personalEditState').textContent='Edit '+t.symbol+' transaction';personalType();$('#personalForm').scrollIntoView({block:'center'});$('#personalSymbol').focus()}
  if(remove&&!personalBusy){const t=workspaceState.portfolioTransactions.find(t=>t.id===remove.dataset.personalDelete);if(!t)return;personalBusy=true;const ok=await workspaceAction({kind:'portfolioDelete',id:t.id,revision:workspaceState.portfolioRevision||0});personalBusy=false;if(ok){$('#personalFormStatus').innerHTML='Transaction removed. <button type="button" id="personalUndo">Undo</button>';$('#personalUndo').onclick=async()=>{await workspaceAction({kind:'portfolioSave',revision:workspaceState.portfolioRevision||0,transaction:t});$('#personalFormStatus').textContent='Restore requested';renderPersonal()}}renderPersonal()}
 });
 $('#personalExport').onclick=()=>{const cols=['date','symbol','type','quantity','price','currency','fees','notes'],cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"',csv=[cols.join(','),...(workspaceState.portfolioTransactions||[]).map(t=>cols.map(k=>cell(t[k])).join(','))].join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='poor-portfolio.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
})();
